import sys

def main():
    input = sys.stdin.readline
    n = int(input().strip())
    a = list(map(int, input().split()))

    first = -1
    last = -1

    for i in range(n):
        if a[i] == 1:
            if first == -1:
                first = i
            last = i

    if first == -1:
        print(0)
        return

    # She stays at the university only during the segment from
    # the first existing class to the last existing class,
    # excluding breaks of length at least 2 (she goes home then).
    ans = 0
    i = first
    while i <= last:
        if a[i] == 1:
            ans += 1
            i += 1
        else:
            j = i
            while j <= last and a[j] == 0:
                j += 1
            gap = j - i
            if gap == 1:
                ans += 1
            i = j

    print(ans)

